647	// ListRules returns a device's rules, ordered by rule id.
648	func (s *Store) ListRules(id string) ([]Rule, error) {
649		s.mu.RLock()
650		defer s.mu.RUnlock()
651		state, ok := s.devices[id]
652		if !ok {
653			return nil, ErrDeviceNotFound
654		}
655		rules := make([]Rule, 0, len(state.rules))
656		for _, rs := range state.rules {
657			rules = append(rules, cloneRule(rs.rule))
658		}
659		sort.Slice(rules, func(i, j int) bool { return rules[i].ID < rules[j].ID })
660		return rules, nil
661	}
662	
663	// AckAlert records the server time of the first acknowledgment. Repeated
664	// acknowledgments keep the original time and write nothing. It returns
665	// ErrDeviceNotFound for an unknown device and ErrAlertNotFound for an unknown
666	// alert id.
667	func (s *Store) AckAlert(id string, alertID int64) (Alert, error) {
668		s.mu.Lock()
669		defer s.mu.Unlock()
670		state, ok := s.devices[id]
671		if !ok {
672			return Alert{}, ErrDeviceNotFound
673		}
674		if alertID < 1 || int(alertID) > len(state.alerts) {
675			return Alert{}, ErrAlertNotFound
676		}
677		alert := state.alerts[alertID-1]
678		if alert.AcknowledgedAt != nil {
679			return cloneAlert(*alert), nil
680		}
681		now := s.now().UTC()
682		if s.wal != nil {
683			if err := s.wal.appendRecord(recAlertAck, walAlertAck{
684				DeviceID: id, AlertID: alertID, AcknowledgedAt: now,
685			}); err != nil {
686				return Alert{}, storageUnavailable(err)
687			}
688		}
689		alert.AcknowledgedAt = &now
690		return cloneAlert(*alert), nil
691	}
692	
693	// ListAlerts returns a device's alerts with the given filters, ordered by
694	// alert id.
695	func (s *Store) ListAlerts(id string, filter AlertFilter) ([]Alert, error) {
696		s.mu.RLock()
697		defer s.mu.RUnlock()
698		state, ok := s.devices[id]
699		if !ok {
700			return nil, ErrDeviceNotFound
701		}
702		if filter.RuleID != "" {
703			if _, ok := state.rules[filter.RuleID]; !ok {
704				return nil, ErrRuleNotFound
705			}
706		}
707		alerts := make([]Alert, 0, len(state.alerts))
708		for _, alert := range state.alerts {
709			if filter.RuleID != "" && alert.RuleID != filter.RuleID {
710				continue
711			}
712			if filter.Status != "" && alert.Status != filter.Status {
713				continue
714			}
715			if filter.Acknowledged != nil {
716				acknowledged := alert.AcknowledgedAt != nil
717				if *filter.Acknowledged != acknowledged {
718					continue
719				}
720			}
721			alerts = append(alerts, cloneAlert(*alert))
722		}
723		return alerts, nil
724	}
725	
726	// alertEvaluator applies accepted samples to a device's enabled rules without
727	// mutating state until commit. It tracks which rule currently has an active
728	// alert so a trigger and a recovery inside the same batch are both handled in
729	// order.
730	type alertEvaluator struct {
731		state        *deviceState
732		activeByRule map[string]int64 // ruleID -> active alert id (0 when none)
733		created      []*Alert
734		ended        []*Alert
735		nextID       int64
736	}
737	
738	func newAlertEvaluator(state *deviceState) *alertEvaluator {
739		eval := &alertEvaluator{
740			state:        state,
741			activeByRule: make(map[string]int64, len(state.rules)),
742			nextID:       int64(len(state.alerts)) + 1,
743		}
744		for id, rs := range state.rules {
745			eval.activeByRule[id] = rs.activeAlertID
746		}
747		return eval
748	}
749	
750	// evaluate judges one accepted sample. A value at or above the trigger opens
751	// an alert (or keeps the existing one); a value at or below the recovery
752	// threshold ends the active alert; anything in between or a missing metric
753	// leaves state unchanged.
754	func (eval *alertEvaluator) evaluate(seq int64, observedAt time.Time, values map[string]float64) {
755		for _, rs := range eval.state.rules {
756			if !rs.rule.Enabled {
757				continue
758			}
759			value, ok := values[rs.rule.Metric]
760			if !ok {
761				continue
762			}
763			activeID := eval.activeByRule[rs.rule.ID]
764			if value >= rs.rule.Trigger && activeID == 0 {
765				alert := &Alert{
766					ID:                eval.nextID,
767					RuleID:            rs.rule.ID,
768					RuleVersion:       rs.rule.Version,
769					Metric:            rs.rule.Metric,
770					Trigger:           rs.rule.Trigger,
771					Recover:           rs.rule.Recover,
772					Status:            alertStatusActive,
773					TriggerSequence:   seq,
774					TriggerValue:      value,
775					TriggerObservedAt: observedAt,
776				}
777				eval.nextID++
778				eval.created = append(eval.created, alert)
779				eval.activeByRule[rs.rule.ID] = alert.ID
780			} else if value <= rs.rule.Recover && activeID != 0 {
781				var source *Alert
782				if activeID <= int64(len(eval.state.alerts)) {
783					source = eval.state.alerts[activeID-1]
784				} else {
785					source = eval.created[activeID-int64(len(eval.state.alerts))-1]
786				}
787				alert := cloneAlert(*source)
788				alert.Status = alertStatusEnded
789				alert.EndReason = endReasonRecovered
790				alert.RecoverSequence = &seq
791				alert.RecoverValue = &value
792				alert.RecoverObservedAt = &observedAt
793				eval.ended = append(eval.ended, &alert)
794				eval.activeByRule[rs.rule.ID] = 0
795			}
796		}
797	}
798	
799	// commit publishes the planned alert changes to the device state.
800	func (eval *alertEvaluator) commit() {
801		applyAlertChanges(eval.state, eval.created, eval.ended)
802	}
803	
804	// applyAlertChanges appends created alerts and replaces ended ones, keeping
805	// each rule's active-alert pointer in sync. It is shared by live evaluation
806	// and WAL recovery.
807	func applyAlertChanges(state *deviceState, created, ended []*Alert) {
808		for _, alert := range created {
809			state.alerts = append(state.alerts, alert)
810			if rs, ok := state.rules[alert.RuleID]; ok {
811				rs.activeAlertID = alert.ID
812			}
813		}
814		for _, alert := range ended {
815			state.alerts[alert.ID-1] = alert
816			if rs, ok := state.rules[alert.RuleID]; ok && rs.activeAlertID == alert.ID {
817				rs.activeAlertID = 0
818			}
819		}
820	}
821	
822	func cloneRule(rule Rule) Rule {
823		return rule
824	}
825	
826	func cloneAlert(alert Alert) Alert {
827		if alert.RecoverSequence != nil {
828			seq := *alert.RecoverSequence
829			alert.RecoverSequence = &seq
830		}
831		if alert.RecoverValue != nil {
832			value := *alert.RecoverValue
833			alert.RecoverValue = &value
834		}
835		if alert.RecoverObservedAt != nil {
836			t := *alert.RecoverObservedAt
837			alert.RecoverObservedAt = &t
838		}
839		if alert.EndedAt != nil {
840			t := *alert.EndedAt
841			alert.EndedAt = &t
842		}
843		if alert.AcknowledgedAt != nil {
844			t := *alert.AcknowledgedAt
845			alert.AcknowledgedAt = &t
846		}
847		return alert
848	}
849	
850	func cloneAlerts(alerts []*Alert) []*Alert {
851		if alerts == nil {
852			return nil
853		}
854		cloned := make([]*Alert, len(alerts))
855		for i, alert := range alerts {
856			c := cloneAlert(*alert)
857			cloned[i] = &c
858		}
859		return cloned
860	}
861	
862	// historyGoneError carries the current earliest retained sequence alongside
863	// ErrHistoryGone so a 410 response can tell the client where the surviving
864	// history resumes.
865	type historyGoneError struct {
866		earliestSequence int64
867	}
868	
869	func (e *historyGoneError) Error() string { return ErrHistoryGone.Error() }
870	func (e *historyGoneError) Unwrap() error { return ErrHistoryGone }
871	
872	// History returns one page of a device's event history. startSeq is the first
873	// receive sequence to scan (1 or 0 for the first page, which begins at the
874	// current earliest retained event); limit caps the number of matching events
875	// returned. bound pins the scan to sequences no larger than bound; a zero
876	// bound means "current maximum", which is then returned so callers can pin
877	// subsequent pages. nextStart is the sequence a following page should start at
878	// when hasMore is true. Retention may have removed the start of a continuation
879	// page: then ErrHistoryGone is returned with the current earliest sequence, so
880	// the missing range is never skipped silently. Concurrent writes cannot skip
881	// or duplicate rows within a paged walk.
882	func (s *Store) History(id string, filter HistoryFilter, startSeq, bound int64, limit int) (events []Event, appliedBound, nextStart int64, hasMore bool, err error) {
883		s.mu.RLock()
884		defer s.mu.RUnlock()
885		state, ok := s.devices[id]
886		if !ok {
887			return nil, 0, 0, false, ErrDeviceNotFound
888		}
889		highWater := state.maxSequence()
890		if bound == 0 {
891			bound = highWater
892		}
893		continuation := startSeq > 0
894		if !continuation {
895			startSeq = state.earliestSequence()
896			if startSeq == 0 {
897				startSeq = 1
898			}
899		} else if startSeq < state.earliestSequence() || startSeq > state.maxSequence() {
900			// The exact record the continuation starts at (or a prefix containing
901			// it) was trimmed. Report 410 with the live window's first sequence
902			// instead of silently resuming partway through the pinned range.
903			return nil, bound, 0, false, &historyGoneError{earliestSequence: state.earliestSequence()}
904		}
905		events = make([]Event, 0, limit)
906		for seq := startSeq; seq <= bound; seq++ {
907			event := state.events[seq-1-state.eventBase]
908			if !filter.From.IsZero() && event.ObservedAt.Before(filter.From) {
909				continue
910			}
911			if !filter.To.IsZero() && event.ObservedAt.After(filter.To) {
912				continue
913			}
914			if len(events) < limit {
915				events = append(events, cloneEvent(event))
916				continue
917			}
918			// This match belongs to the next page; resume scanning at its sequence
919			// so rows in the gap are never examined twice.
920			return events, bound, seq, true, nil
921		}
922		return events, bound, 0, false, nil
923	}
924	
925	func (s *Store) Snapshot() []Device {
926		s.mu.RLock()
927		defer s.mu.RUnlock()
928		result := make([]Device, 0, len(s.devices))
929		for _, state := range s.devices {
930			result = append(result, cloneDevice(state.device))
931		}
932		sort.Slice(result, func(i, j int) bool { return result[i].ID < result[j].ID })
933		return result
934	}
935	
936	func cloneDevice(device Device) Device {
937		device.LastTelemetry = cloneTelemetry(device.LastTelemetry)
938		return device
939	}
940	
941	func cloneEvent(event Event) Event {
942		event.Values = cloneTelemetry(event.Values)
943		return event
944	}
945	
946	func cloneTelemetry(values map[string]float64) map[string]float64 {
947		if values == nil {
948			return nil
949		}
950		cloned := make(map[string]float64, len(values))
951		for key, value := range values {
952			cloned[key] = value
953		}
954		return cloned
955	}
956	
957	// sameInstant compares times as UTC instants.
958	func sameInstant(a, b time.Time) bool {
959		return a.UTC().Equal(b.UTC())
960	}
961	
962	// sameValues compares metric maps by key and value.
963	func sameValues(a, b map[string]float64) bool {
964		if len(a) != len(b) {
965			return false
966		}
967		for key, value := range a {
968			other, ok := b[key]
969			if !ok || value != other {
970				return false
971			}
972		}
973		return true
974	}
975	
976	// sameOrderedSamples reports whether two batches carry the same samples in the
977	// same order, compared as UTC instants and key/value maps.
978	func sameOrderedSamples(a, b []Sample) bool {
979		if len(a) != len(b) {
980			return false
981		}
982		for i := range a {
983			if a[i].EventID != b[i].EventID ||
984				!sameInstant(a[i].ObservedAt, b[i].ObservedAt) ||
985				!sameValues(a[i].Values, b[i].Values) {
986				return false
987			}
988		}
989		return true
990	}
991

