11	
12	func TestPersistentTaskCreateRestores(t *testing.T) {
13		dir := t.TempDir()
14		store := openPersistent(t, dir)
15		h := NewHandler(store)
16		mustRegister(t, h, "gw")
17	
18		createTask(t, h, "gw", taskBody("req-1", 30), http.StatusCreated)
19		createTask(t, h, "gw", taskBody("req-2", 45), http.StatusCreated)
20		if err := store.Close(); err != nil {
21			t.Fatal(err)
22		}
23	
24		store2 := reopenPersistent(t, dir)
25		h2 := NewHandler(store2)
26	
27		list := decodeBody[struct {
28			Tasks []taskResponse `json:"tasks"`
29		}](t, doRequest(t, h2, http.MethodGet, "/v1/devices/gw/tasks", ""))
30		if len(list.Tasks) != 2 || list.Tasks[0].ID != 1 || list.Tasks[1].ID != 2 {
31			t.Fatalf("tasks after restart = %+v", list.Tasks)
32		}
33		if list.Tasks[0].Status != "pending" || list.Tasks[0].DurationSeconds != 30 {
34			t.Fatalf("task 1 after restart = %+v", list.Tasks[0])
35		}
36	
37		// requestId dedup survives: same content -> 200, different duration -> 409.
38		createTask(t, h2, "gw", taskBody("req-1", 30), http.StatusOK)
39		createTask(t, h2, "gw", taskBody("req-1", 45), http.StatusConflict)
40	
41		// Audit survives with the create record.
42		audit := listAudit(t, h2, "gw", 1)
43		if len(audit) != 1 || audit[0].Event != "created" || audit[0].ToStatus != "pending" {
44			t.Fatalf("audit after restart = %+v", audit)
45		}
46	}
